export interface TournamentSession extends ClockSession {
  readonly game: GameState | null;
  readonly tournament: Tournament | null;
}

function emptySession(generation = 0): TournamentSession {
  return { game: null, generation, paused: false, tournament: null };
}

function tickTournament(session: TournamentSession, generation: number, milliseconds: number): TournamentSession {
  if (
    session.generation !== generation || session.tournament?.phase !== 'playing' || !session.game
  )
    return session;
  const game = advanceGame(session.game, milliseconds);
  return game === session.game ? session : { ...session, game };
}

function completedSetup(tournament: Tournament): TournamentSetup {
