import type { PlayerCount } from './rules.ts';

export type PlayerNameCheck =
  | { readonly ok: true; readonly names: readonly string[] }
  | { readonly ok: false; readonly error: string };

export function normalizePlayerName(value: string): string {
  return value.trim().replace(/\s+/gu, ' ').normalize('NFC');
}

export function isValidPlayerName(name: string): boolean {
  const length = Array.from(name).length;
  return length >= 2 && length <= 20;
}

export function validatePlayerNames(values: readonly string[], count: PlayerCount): PlayerNameCheck {
  if (values.length !== count) return { ok: false, error: 'Enter a name for every player.' };
  const names = values.map(normalizePlayerName);
  if (names.some((name) => !isValidPlayerName(name)))
    return { ok: false, error: 'Use 2 to 20 characters.' };
  const seen = new Set<string>();
  for (const name of names) {
    const key = name.toLowerCase();
    if (seen.has(key)) return { ok: false, error: 'Each name must be different.' };
    seen.add(key);
  }
  return { ok: true, names };
}

import { useEffect, useLayoutEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import type { GameState } from '../game.ts';
import type { RefObject } from 'react';

export interface ClockSession {
  readonly game: GameState | null;
  readonly paused: boolean;
  readonly generation: number;
}

export function useGameClock<S extends ClockSession>(
  session: S,
  current: RefObject<S>,
  commit: (next: S) => void,
  tick: (session: S, generation: number, milliseconds: number) => S,
  active = true,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const foreground = useRef(active);
  const won = session.game ? isWon(session.game) : false;

  function running(): boolean {
    const latest = current.current;
    return (
      foreground.current &&
      visible.current &&
      !latest.paused &&
      latest.game !== null &&
      latest.game.started &&
      !isWon(latest.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const step = elapsedStep(clock.current, performance.now(), running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tick(current.current, generation, step.milliseconds));
  }

  useLayoutEffect(() => {
    if (foreground.current === active) return;
    synchronize();
    foreground.current = active;
  }, [active]);

  useEffect(() => {
    const generation = session.generation;
    let mounted = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!mounted || generation !== current.current.generation || !running()) return;
      const selection = current.current.game?.selection;
      const delay =
        selection?.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!mounted) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!mounted || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      mounted = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [active, session.generation, session.game?.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { ELAPSED_MAX_MS } from '../game.ts';
import { validatePlayerNames } from './names.ts';
import { createTournament } from './pairing.ts';
import { validateTournamentProgress } from './format-progress.ts';
import type { MatchResult, PlayerCount, RoundName, Tournament, TournamentMatch, TournamentPhase, TournamentRound } from './rules.ts';
import type { GameState } from '../game.ts';

function playerCount(value: unknown): PlayerCount | null {
  return value === 4 || value === 8 ? value : null;
}

function playerSlot(value: unknown): string | null | undefined {
  if (value === null || typeof value === 'string') return value;
  return undefined;
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === 'string');
}

function roundName(value: unknown): RoundName | null {
  return value === 'Quarterfinal' || value === 'Semifinal' || value === 'Final' ? value : null;
}

function readResult(value: unknown): MatchResult | null | undefined {
  if (value === null) return null;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['elapsedMs', 'moves', 'name']) ||
    typeof value.name !== 'string' ||
    !isNonnegativeSafeInteger(value.moves) ||
    typeof value.elapsedMs !== 'number' ||
    !Number.isFinite(value.elapsedMs) ||
    value.elapsedMs < 0 ||
    value.elapsedMs > ELAPSED_MAX_MS
  )
    return undefined;
  return { name: value.name, moves: value.moves, elapsedMs: value.elapsedMs };
}

function readMatch(value: unknown): TournamentMatch | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['boardCode', 'players', 'results', 'winner']) ||
    typeof value.boardCode !== 'string' ||
    !Array.isArray(value.players) || value.players.length !== 2 ||
    !Array.isArray(value.results) || value.results.length !== 2
  )
    return null;
  const firstPlayer = playerSlot(value.players[0]);
  const secondPlayer = playerSlot(value.players[1]);
  const firstResult = readResult(value.results[0]);
  const secondResult = readResult(value.results[1]);
  if (
    firstPlayer === undefined || secondPlayer === undefined ||
    firstResult === undefined || secondResult === undefined ||
    (value.winner !== null && typeof value.winner !== 'string')
  )
    return null;
  return {
    boardCode: value.boardCode,
    players: [firstPlayer, secondPlayer],
    results: [firstResult, secondResult],
    winner: value.winner,
  };
}

function readRound(value: unknown): TournamentRound | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['matches', 'name', 'size']) ||
    typeof value.name !== 'string' ||
    typeof value.size !== 'number' ||
    !Array.isArray(value.matches)
  )
    return null;
  const name = roundName(value.name);
  if (!name) return null;
  const matches: TournamentMatch[] = [];
  for (const entry of value.matches) {
    const match = readMatch(entry);
    if (!match) return null;
    matches.push(match);
  }
  return { name, size: value.size, matches };
}

function phase(value: unknown): TournamentPhase | null {
  return value === 'ready' || value === 'playing' || value === 'next-turn' || value === 'next-match' || value === 'complete'
    ? value
    : null;
}

export interface TournamentSetup {
  readonly playerCount: PlayerCount;
  readonly players: readonly string[];
}

export function readSetup(value: unknown): TournamentSetup | null {
  if (!isJsonObject(value) || !hasExactKeys(value, ['playerCount', 'players']) || !isStringArray(value.players))
    return null;
  const count = playerCount(value.playerCount);
  if (count === null || value.players.length !== 8)
    return null;
  return { playerCount: count, players: value.players };
}

export function readTournament(value: unknown, game: GameState | null): Tournament | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['matchIndex', 'playerCount', 'playerIndex', 'phase', 'players', 'roundIndex', 'rounds']) ||
    !isStringArray(value.players) || !Array.isArray(value.rounds)
  )
    return null;
  const count = playerCount(value.playerCount);
  const currentPhase = phase(value.phase);
  if (
    count === null || currentPhase === null || value.players.length !== count ||
    !isNonnegativeSafeInteger(value.roundIndex) || !isNonnegativeSafeInteger(value.matchIndex) ||
    (value.playerIndex !== 0 && value.playerIndex !== 1)
  )
    return null;
  const players = value.players;
  const names = validatePlayerNames(players, count);
  if (!names.ok || names.names.some((name, index) => name !== players[index])) return null;
  const validRounds: TournamentRound[] = [];
  for (const entry of value.rounds) {
    const round = readRound(entry);
    if (!round) return null;
    validRounds.push(round);
  }
  const codes = validRounds.flatMap((round) => round.matches.map((match) => match.boardCode));
  const expected = createTournament(players, codes);
  if (!expected || validRounds.length !== expected.rounds.length) return null;
  const tournament: Tournament = {
    matchIndex: value.matchIndex,
    playerCount: count,
    playerIndex: value.playerIndex,
    phase: currentPhase,
    players,
    roundIndex: value.roundIndex,
    rounds: validRounds,
  };
  for (const [r, round] of validRounds.entries()) {
    const baseline = expected.rounds[r];
    if (!baseline || round.name !== baseline.name || round.size !== baseline.size || round.matches.length !== baseline.matches.length)
      return null;
    for (const [m, match] of round.matches.entries()) {
      const priorRound = validRounds[r - 1];
      const expectedPlayers = r === 0
        ? baseline.matches[m]?.players
        : [priorRound?.matches[m * 2]?.winner ?? null, priorRound?.matches[m * 2 + 1]?.winner ?? null];
      if (!expectedPlayers || match.players[0] !== expectedPlayers[0] || match.players[1] !== expectedPlayers[1]) return null;
    }
  }
  return validateTournamentProgress(tournament, game) ? tournament : null;
}
import { ELAPSED_MAX_MS, MOVES_MAX, isWon } from '../game.ts';
import { isNonnegativeSafeInteger } from '../saved-format.ts';
import { compareResults, tournamentMatch } from './rules.ts';
import type { GameState } from '../game.ts';
import type { MatchResult, Tournament, TournamentMatch } from './rules.ts';

function resultFits(result: MatchResult | null, name: string | null, size: number): boolean {
  return result === null || (
    name !== null && result.name === name &&
    isNonnegativeSafeInteger(result.moves) && result.moves >= (size * size) / 2 &&
    result.moves <= MOVES_MAX && Number.isFinite(result.elapsedMs) &&
    result.elapsedMs >= 0 && result.elapsedMs <= ELAPSED_MAX_MS
  );
}

function matchIsFinished(match: TournamentMatch): boolean {
  return match.results[0] !== null && match.results[1] !== null && match.winner !== null;
}

function validateResults(rounds: Tournament['rounds'], players: readonly string[]): boolean {
  for (const round of rounds) {
    for (const match of round.matches) {
      const [first, second] = match.players;
      const [firstResult, secondResult] = match.results;
      if (!resultFits(firstResult, first, round.size) || !resultFits(secondResult, second, round.size))
        return false;
      if ((match.winner === null) !== (firstResult === null || secondResult === null)) return false;
      if (match.winner !== null) {
        if (!first || !second || !firstResult || !secondResult) return false;
        const winner = compareResults(
          firstResult,
          secondResult,
          players.indexOf(first),
          players.indexOf(second),
        ) <= 0 ? first : second;
        if (match.winner !== winner) return false;
      }
    }
  }
  return true;
}

export function validateTournamentProgress(tournament: Tournament, game: GameState | null): boolean {
  if (!validateResults(tournament.rounds, tournament.players)) return false;
  const { roundIndex, matchIndex, phase, playerIndex, rounds } = tournament;
  const currentRound = rounds[roundIndex];
  const current = tournamentMatch(tournament);
  if (!currentRound || !current) return false;
  for (const [r, round] of rounds.entries()) {
    for (const [m, match] of round.matches.entries()) {
      const before = r < roundIndex || (r === roundIndex && m < matchIndex);
      const after = r > roundIndex || (r === roundIndex && m > matchIndex);
      if (before && !matchIsFinished(match)) return false;
      if (after && (match.results.some((result) => result !== null) || match.winner !== null)) return false;
    }
  }
  const finished = phase === 'next-match' || phase === 'complete';
  if (finished !== matchIsFinished(current)) return false;
  if (phase === 'next-turn' && (playerIndex !== 0 || !current.results[0] || current.results[1])) return false;
  if ((phase === 'ready' || phase === 'playing') &&
      (playerIndex === 0 ? current.results.some((result) => result !== null) : !current.results[0] || current.results[1]))
    return false;
  if (finished && (playerIndex !== 1 || !current.winner)) return false;
  const finalMatch = roundIndex === rounds.length - 1 && matchIndex === currentRound.matches.length - 1;
  if (finished && (phase === 'complete') !== finalMatch) return false;
  if (phase === 'playing') return game !== null && game.boardCode === current.boardCode && !isWon(game);
  if (phase === 'next-turn' || phase === 'next-match')
    return game !== null && game.boardCode === current.boardCode && isWon(game);
  return game === null;
}
