 34	function readResult(value: unknown): MatchResult | null | undefined {
 35	  if (value === null) return null;
 36	  if (
 37	    !isJsonObject(value) ||
 38	    !hasExactKeys(value, ['elapsedMs', 'moves', 'name']) ||
 39	    typeof value.name !== 'string' ||
 40	    !isNonnegativeSafeInteger(value.moves) ||
 41	    typeof value.elapsedMs !== 'number' ||
 42	    !Number.isFinite(value.elapsedMs) ||
 43	    value.elapsedMs < 0 ||
 44	    value.elapsedMs > ELAPSED_MAX_MS
 45	  )
 46	    return undefined;
 47	  return { name: value.name, moves: value.moves, elapsedMs: value.elapsedMs };
 48	}
 49	
 50	function readMatch(value: unknown): TournamentMatch | null {
 51	  if (
 52	    !isJsonObject(value) ||
 53	    !hasExactKeys(value, ['boardCode', 'players', 'results', 'winner']) ||
 54	    typeof value.boardCode !== 'string' ||
 55	    !Array.isArray(value.players) ||
 56	    value.players.length !== 2 ||
 57	    !Array.isArray(value.results) ||
 58	    value.results.length !== 2
 59	  )
 60	    return null;
 61	  const firstPlayer = playerSlot(value.players[0]);
 62	  const secondPlayer = playerSlot(value.players[1]);
 63	  const firstResult = readResult(value.results[0]);
 64	  const secondResult = readResult(value.results[1]);
 65	  if (
 66	    firstPlayer === undefined ||
 67	    secondPlayer === undefined ||
 68	    firstResult === undefined ||
 69	    secondResult === undefined ||
 70	    (value.winner !== null && typeof value.winner !== 'string')
 71	  )
 72	    return null;
 73	  return {
 74	    boardCode: value.boardCode,
 75	    players: [firstPlayer, secondPlayer],
 76	    results: [firstResult, secondResult],
 77	    winner: value.winner,
