 81	function readRound(value: unknown): TournamentRound | null {
 82	  if (
 83	    !isJsonObject(value) ||
 84	    !hasExactKeys(value, ['matches', 'name', 'size']) ||
 85	    typeof value.name !== 'string' ||
 86	    typeof value.size !== 'number' ||
 87	    !Array.isArray(value.matches)
 88	  )
 89	    return null;
 90	  const name = roundName(value.name);
 91	  if (!name) return null;
 92	  const matches: TournamentMatch[] = [];
 93	  for (const entry of value.matches) {
