113	  readonly players: readonly string[];
114	}
115	
116	export function readSetup(value: unknown): TournamentSetup | null {
117	  if (
118	    !isJsonObject(value) ||
119	    !hasExactKeys(value, ['playerCount', 'players']) ||
120	    !isStringArray(value.players)
121	  )
122	    return null;
123	  const count = playerCount(value.playerCount);
124	  if (count === null || value.players.length !== 8) return null;
125	  return { playerCount: count, players: value.players };
126	}
127	
128	export function readTournament(value: unknown, game: GameState | null): Tournament | null {
129	  if (
130	    !isJsonObject(value) ||
131	    !hasExactKeys(value, [
132	      'matchIndex',
133	      'playerCount',
134	      'playerIndex',
135	      'phase',
136	      'players',
137	      'roundIndex',
138	      'rounds',
139	    ]) ||
140	    !isStringArray(value.players) ||
141	    !Array.isArray(value.rounds)
142	  )
143	    return null;
144	  const count = playerCount(value.playerCount);
145	  const currentPhase = phase(value.phase);
146	  if (
147	    count === null ||
148	    currentPhase === null ||
149	    value.players.length !== count ||
150	    !isNonnegativeSafeInteger(value.roundIndex) ||
151	    !isNonnegativeSafeInteger(value.matchIndex) ||
152	    (value.playerIndex !== 0 && value.playerIndex !== 1)
153	  )
154	    return null;
155	  const players = value.players;
156	  const names = validatePlayerNames(players, count);
157	  if (!names.ok || names.names.some((name, index) => name !== players[index])) return null;
158	  const validRounds: TournamentRound[] = [];
159	  for (const entry of value.rounds) {
160	    const round = readRound(entry);
161	    if (!round) return null;
162	    validRounds.push(round);
163	  }
164	  const codes = validRounds.flatMap((round) => round.matches.map((match) => match.boardCode));
165	  const expected = createTournament(players, codes);
166	  if (!expected || validRounds.length !== expected.rounds.length) return null;
167	  const tournament: Tournament = {
168	    matchIndex: value.matchIndex,
169	    playerCount: count,
170	    playerIndex: value.playerIndex,
171	    phase: currentPhase,
172	    players,
173	    roundIndex: value.roundIndex,
174	    rounds: validRounds,
175	  };
176	  for (const [r, round] of validRounds.entries()) {
177	    const baseline = expected.rounds[r];
178	    if (
179	      !baseline ||
180	      round.name !== baseline.name ||
181	      round.size !== baseline.size ||
182	      round.matches.length !== baseline.matches.length
183	    )
184	      return null;
185	    for (const [m, match] of round.matches.entries()) {
186	      const priorRound = validRounds[r - 1];
187	      const expectedPlayers =
188	        r === 0
189	          ? baseline.matches[m]?.players
190	          : [
191	              priorRound?.matches[m * 2]?.winner ?? null,
192	              priorRound?.matches[m * 2 + 1]?.winner ?? null,
193	            ];
194	      if (
195	        !expectedPlayers ||
196	        match.players[0] !== expectedPlayers[0] ||
197	        match.players[1] !== expectedPlayers[1]
198	      )
199	        return null;
200	    }
201	  }
202	  return validateTournamentProgress(tournament, game) ? tournament : null;
203	}

